CREATE TYPE "SimulationExecutionMode" AS ENUM ('SIMULATION','STAGING','SYNTHETIC_PRODUCTION','CONTROLLED_PRODUCTION');
CREATE TYPE "SimulationScenarioType" AS ENUM ('DEPENDENCY_FAILURE','API_CHANGE','DATABASE_CHANGE','EVENT_CHANGE','JOB_FAILURE','QUEUE_BACKLOG','CACHE_FAILURE','SEARCH_FAILURE','NOTIFICATION_FAILURE','PROVIDER_FAILURE','PAYMENT_SIMULATION','CHECKOUT_SIMULATION','ORDER_SIMULATION','FULFILLMENT_SIMULATION','SHIPPING_SIMULATION','RETURN_SIMULATION','CUSTOMER_JOURNEY','DEPLOYMENT_CHANGE','FEATURE_FLAG_CHANGE','CAPACITY_CHANGE','SECURITY_CONTROL_CHANGE','ARCHITECTURAL_CHANGE');
CREATE TYPE "SimulationLifecycle" AS ENUM ('DRAFT','REVIEW_REQUIRED','APPROVED','READY','RUNNING','ASSERTING','COMPLETED','CERTIFIED','FAILED','BLOCKED','ABORTED','REJECTED','EXPIRED');
CREATE TYPE "SimulationRisk" AS ENUM ('MINIMAL','LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "SimulationRunStatus" AS ENUM ('RUNNING','ASSERTING','COMPLETED','FAILED','BLOCKED','ABORTED');
CREATE TYPE "SimulationResultStatus" AS ENUM ('PASSED','PASSED_WITH_LIMITATIONS','FAILED','BLOCKED');
CREATE TYPE "SimulationCertificationFreshness" AS ENUM ('CURRENT','AGING','STALE','INVALIDATED');
CREATE TYPE "SimulationAssertionResult" AS ENUM ('PASSED','FAILED','UNKNOWN','BLOCKED');
CREATE TABLE "SimulationScenario" (
"id" UUID NOT NULL,"stableId" VARCHAR(200) NOT NULL,"name" VARCHAR(240) NOT NULL,"description" VARCHAR(4000) NOT NULL,"purpose" VARCHAR(2000) NOT NULL,"owner" VARCHAR(160) NOT NULL,"scenarioVersion" INTEGER NOT NULL DEFAULT 1,"type" "SimulationScenarioType" NOT NULL,"environment" VARCHAR(80) NOT NULL,"executionMode" "SimulationExecutionMode" NOT NULL,"scope" JSONB NOT NULL,"risk" "SimulationRisk" NOT NULL,"dependencies" JSONB NOT NULL,"inputs" JSONB NOT NULL,"expectedOutputs" JSONB NOT NULL,"assertions" JSONB NOT NULL,"status" "SimulationLifecycle" NOT NULL DEFAULT 'DRAFT',"approval" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SimulationScenario_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SimulationScenario_stableId_key" ON "SimulationScenario"("stableId");
CREATE INDEX "SimulationScenario_status_risk_updatedAt_idx" ON "SimulationScenario"("status","risk","updatedAt");
CREATE INDEX "SimulationScenario_type_environment_idx" ON "SimulationScenario"("type","environment");
CREATE TABLE "SimulationInput" ("id" UUID NOT NULL,"scenarioId" UUID NOT NULL,"key" VARCHAR(160) NOT NULL,"value" JSONB NOT NULL,"syntheticOnly" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "SimulationInput_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SimulationInput_scenarioId_key_key" ON "SimulationInput"("scenarioId","key");
CREATE TABLE "SimulationOutput" ("id" UUID NOT NULL,"scenarioId" UUID NOT NULL,"key" VARCHAR(160) NOT NULL,"value" JSONB NOT NULL,"status" VARCHAR(40) NOT NULL,CONSTRAINT "SimulationOutput_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SimulationOutput_scenarioId_status_idx" ON "SimulationOutput"("scenarioId","status");
CREATE TABLE "SimulationDependency" ("id" UUID NOT NULL,"scenarioId" UUID NOT NULL,"graphNodeStableId" VARCHAR(200) NOT NULL,"role" VARCHAR(80) NOT NULL,"required" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "SimulationDependency_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SimulationDependency_scenarioId_graphNodeStableId_role_key" ON "SimulationDependency"("scenarioId","graphNodeStableId","role");
CREATE TABLE "SimulationSnapshot" ("id" UUID NOT NULL,"stableId" VARCHAR(200) NOT NULL,"scenarioId" UUID,"codeVersion" VARCHAR(160) NOT NULL,"schemaVersion" VARCHAR(160) NOT NULL,"configurationVersion" VARCHAR(160) NOT NULL,"featureFlagState" JSONB NOT NULL,"dependencyGraphVersion" VARCHAR(160) NOT NULL,"architectureVersion" VARCHAR(160) NOT NULL,"scenarioVersion" INTEGER NOT NULL,"environment" VARCHAR(80) NOT NULL,"dataFixtureVersion" VARCHAR(160) NOT NULL,"randomSeed" VARCHAR(160),"immutable" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SimulationSnapshot_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SimulationSnapshot_stableId_key" ON "SimulationSnapshot"("stableId");
CREATE INDEX "SimulationSnapshot_scenarioId_createdAt_idx" ON "SimulationSnapshot"("scenarioId","createdAt");
CREATE TABLE "SimulationRun" ("id" UUID NOT NULL,"scenarioId" UUID NOT NULL,"snapshotId" UUID NOT NULL,"status" "SimulationRunStatus" NOT NULL DEFAULT 'RUNNING',"result" "SimulationResultStatus","environment" VARCHAR(80) NOT NULL,"executionMode" "SimulationExecutionMode" NOT NULL,"correlationId" VARCHAR(128) NOT NULL,"lineageId" VARCHAR(160) NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),"randomSeed" VARCHAR(160),"limits" JSONB NOT NULL,"outputs" JSONB,"resourceUsage" JSONB,"abortReason" VARCHAR(1000),"baselineRunId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SimulationRun_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SimulationRun_scenarioId_startedAt_idx" ON "SimulationRun"("scenarioId","startedAt");
CREATE INDEX "SimulationRun_status_startedAt_idx" ON "SimulationRun"("status","startedAt");
CREATE TABLE "SimulationRunInput" ("id" UUID NOT NULL,"runId" UUID NOT NULL,"key" VARCHAR(160) NOT NULL,"value" JSONB NOT NULL,"syntheticOnly" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "SimulationRunInput_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SimulationRunInput_runId_key_key" ON "SimulationRunInput"("runId","key");
CREATE TABLE "SimulationAssertion" ("id" UUID NOT NULL,"runId" UUID NOT NULL,"assertionKey" VARCHAR(160) NOT NULL,"assertionType" VARCHAR(80) NOT NULL,"expected" JSONB NOT NULL,"actual" JSONB,"result" "SimulationAssertionResult" NOT NULL,"severity" "SimulationRisk" NOT NULL,"evidence" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SimulationAssertion_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SimulationAssertion_runId_result_idx" ON "SimulationAssertion"("runId","result");
CREATE TABLE "SimulationFailure" ("id" UUID NOT NULL,"scenarioId" UUID NOT NULL,"runId" UUID,"target" VARCHAR(200) NOT NULL,"scope" VARCHAR(1000) NOT NULL,"expectedBehavior" JSONB NOT NULL,"abortConditions" JSONB NOT NULL,"recoveryExpectation" JSONB NOT NULL,"status" VARCHAR(40) NOT NULL,"metadata" JSONB NOT NULL,CONSTRAINT "SimulationFailure_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SimulationFailure_scenarioId_status_idx" ON "SimulationFailure"("scenarioId","status");
CREATE INDEX "SimulationFailure_target_status_idx" ON "SimulationFailure"("target","status");
CREATE TABLE "SimulationImpact" ("id" UUID NOT NULL,"scenarioId" UUID NOT NULL,"runId" UUID,"changeReference" VARCHAR(300) NOT NULL,"directlyAffected" JSONB NOT NULL,"indirectlyAffected" JSONB NOT NULL,"affectedDomains" JSONB NOT NULL,"affectedApis" JSONB NOT NULL,"affectedTables" JSONB NOT NULL,"affectedWorkflows" JSONB NOT NULL,"affectedJourneys" JSONB NOT NULL,"affectedProviders" JSONB NOT NULL,"affectedSlos" JSONB NOT NULL,"affectedGovernance" JSONB NOT NULL,"affectedReconciliation" JSONB NOT NULL,"affectedResilience" JSONB NOT NULL,"affectedDigitalTwin" JSONB NOT NULL,"blastRadius" "SimulationRisk" NOT NULL,"summary" VARCHAR(4000) NOT NULL,CONSTRAINT "SimulationImpact_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SimulationImpact_scenarioId_blastRadius_idx" ON "SimulationImpact"("scenarioId","blastRadius");
CREATE INDEX "SimulationImpact_changeReference_idx" ON "SimulationImpact"("changeReference");
CREATE TABLE "SimulationEvidence" ("id" UUID NOT NULL,"runId" UUID NOT NULL,"evidenceType" VARCHAR(100) NOT NULL,"reference" VARCHAR(1000) NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"payload" JSONB NOT NULL,"immutable" BOOLEAN NOT NULL DEFAULT true,"capturedBy" VARCHAR(160),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SimulationEvidence_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SimulationEvidence_runId_createdAt_idx" ON "SimulationEvidence"("runId","createdAt");
CREATE TABLE "SimulationCertification" ("id" UUID NOT NULL,"scenarioId" UUID NOT NULL,"runId" UUID,"status" "SimulationResultStatus" NOT NULL,"freshness" "SimulationCertificationFreshness" NOT NULL DEFAULT 'CURRENT',"dimensions" JSONB NOT NULL,"reviewer" VARCHAR(160),"certifiedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"limitations" JSONB NOT NULL,CONSTRAINT "SimulationCertification_pkey" PRIMARY KEY ("id"));
CREATE INDEX "SimulationCertification_scenarioId_status_freshness_idx" ON "SimulationCertification"("scenarioId","status","freshness");
CREATE INDEX "SimulationCertification_expiresAt_idx" ON "SimulationCertification"("expiresAt");
ALTER TABLE "SimulationInput" ADD CONSTRAINT "SimulationInput_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationOutput" ADD CONSTRAINT "SimulationOutput_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationDependency" ADD CONSTRAINT "SimulationDependency_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationSnapshot" ADD CONSTRAINT "SimulationSnapshot_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationRun" ADD CONSTRAINT "SimulationRun_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationRun" ADD CONSTRAINT "SimulationRun_snapshotId_fkey" FOREIGN KEY ("snapshotId") REFERENCES "SimulationSnapshot"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationRunInput" ADD CONSTRAINT "SimulationRunInput_runId_fkey" FOREIGN KEY ("runId") REFERENCES "SimulationRun"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationAssertion" ADD CONSTRAINT "SimulationAssertion_runId_fkey" FOREIGN KEY ("runId") REFERENCES "SimulationRun"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationFailure" ADD CONSTRAINT "SimulationFailure_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationFailure" ADD CONSTRAINT "SimulationFailure_runId_fkey" FOREIGN KEY ("runId") REFERENCES "SimulationRun"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationImpact" ADD CONSTRAINT "SimulationImpact_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationImpact" ADD CONSTRAINT "SimulationImpact_runId_fkey" FOREIGN KEY ("runId") REFERENCES "SimulationRun"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationEvidence" ADD CONSTRAINT "SimulationEvidence_runId_fkey" FOREIGN KEY ("runId") REFERENCES "SimulationRun"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationCertification" ADD CONSTRAINT "SimulationCertification_scenarioId_fkey" FOREIGN KEY ("scenarioId") REFERENCES "SimulationScenario"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SimulationCertification" ADD CONSTRAINT "SimulationCertification_runId_fkey" FOREIGN KEY ("runId") REFERENCES "SimulationRun"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
